      notes = {
        {text = "Junior trainers teach Mining up to 75 and no smelting.", confirmed = false},
        {text = "Poor Copper Vein and Chunk of Amber (Teldrassil) give Copper Ore, and skill only to 20.", confirmed = false},
        {text = "Ore stacks to 20.", confirmed = true},
        {text = "Smelt Azerothium at 275 (2 Pitchblende + 1 Coal, at a forge). Smelt Heavy Thorium at 300 needs a Molten Foundry.", confirmed = true},
        {text = "Scarce materials: Pyrite (from Copper, Tin and Iron), Bauxite (Mithril) and Pitchblende (Thorium).", confirmed = false},
        {text = "A Heavy Thorium Vein grows in Mount Hyjal (the Scourge area).", confirmed = false},
        {text = "Mining makes camp items: a Lodestone at 20, a Rock Garden at 140 and a Molten Foundry at 300.", confirmed = true},
        {text = "The Lodestone gives melee attack power (it doesn't stack with Blessing of Might). The Rock Garden spawns a vein; its blueprint drops from Relic Guardians at the Wetlands Excavation Site.", confirmed = false},
        {text = "Find Minerals now stacks with other tracking, but not with Find Herbs.", confirmed = false},
        {text = "Veins reportedly respawn faster — one source says faster with more players nearby. Reports disagree.", confirmed = false},
        {text = "\"Mining for Dummies\", a reward from early starting-zone quests, teaches Mining with +2 skill, up to 15. On Zephras Isle it comes from the quest \"Harvesting Windstones\".", confirmed = false},
        {text = "The Legacy talent Bountiful Harvest gives more scarce materials. Gathering earns no Legacy points.", confirmed = false},
