        {name = "Artisan", skill = 225, level = 35, cap = 300, trainers = {A = {{name = "Doctor Gustaf VanHowzen", map = 1445, x = 67.8, y = 49, where = "Theramore Isle, Dustwallow Marsh"}}, H = {{name = "Doctor Gregory Victor", map = 1417, x = 73.4, y = 36.9, where = "Hammerfall, Arathi Highlands"}}}, how = {A = "Quest Triage from Doctor Gustaf VanHowzen. Save 15 patients before 6 die, and turn it in the moment you reach 15. Its lead-in, Alliance Trauma, is from Nissa Firestone in Ironforge. Theramore is in Kalimdor — take the boat from Menethil Harbor in the Wetlands to Theramore Isle.", H = "Quest Triage from Doctor Gregory Victor. Save 15 patients before 6 die, and turn it in the moment you reach 15. Its lead-in, Horde Trauma, is from Arnok in Orgrimmar. Hammerfall is in the Eastern Kingdoms — take the zeppelin from Orgrimmar to Undercity, then head south-east to Arathi Highlands."}, confirmed = false},
