      notes = {
        {text = "Forever adds 17 First Aid recipes: healing potions, Poultices, Tourniquets, Anti-Venoms, Toxin Study, a First Aid Kit and a Plague Doctor's Laboratory. Where most of them come from isn't known yet.", confirmed = true},
        {text = "17 Forever recipes: source not known yet. They're marked \"Source unknown\" — no Classic trainer or vendor is named for them, so the route sticks to bandages.", confirmed = true},
        {text = "Healing potions moved from Alchemy to First Aid. Alchemy keeps only \"Discolored\" healing potions.", confirmed = true},
        {text = "The bandages are unchanged from Classic — the same cloth and the same skill colours.", confirmed = true},
        {text = "Expert First Aid – Under Wraps costs 1 gold in the game files.", confirmed = true},
        {text = "First Aid Kit (yellow at 20) is a camp item. Reported in the beta: it buffs your group with Stamina, like Power Word: Fortitude.", confirmed = false},
        {text = "Reported in the beta: trainers teach the low and middle recipes and Minor Healing Potion from skill 1; the higher manuals drop from mobs.", confirmed = false},
        {text = "The Triage quest for Artisan, and who teaches each recipe at what skill, are Classic Era's. Forever may change them.", confirmed = false},
      },
